    #endif

    // MARK: - Notification Categories

    /// Registers notification categories with the system.
    static func registerCategories() {
        let episodeCategory = UNNotificationCategory(
            identifier: NotificationCategory.newEpisode.rawValue,
            actions: [],
            intentIdentifiers: []
