import WCIWKit

/// The user's intent for a watchlist item.
enum WatchState: String, Codable, CaseIterable {
    case tracking
    case watched
}

/// A media item (TV show or movie) that the user is actively tracking in their watchlist.
@Model
final class WatchlistItem {
    /// Unique identifier.
    @Attribute(.unique) var mediaId: Int

    /// Title of the show or movie.
    var title: String

    /// Path to poster image.
    var posterPath: String?

    /// Path to backdrop image.
    var backdropPath: String?

    /// Date the item was added to the watchlist.
    var dateAdded: Date

    /// Raw status string for persistence.
    var statusRaw: String

    /// Raw media type string for persistence (tv or movie).
    /// Optional for backwards compatibility - existing items without this field will be treated as TV shows.
    private var mediaTypeRaw: String?

    /// Next episode air date, if known (TV shows only).
    var nextEpisodeDate: Date?

    /// Next episode number (TV shows only).
    var nextEpisodeNumber: Int?

    /// Next season number (TV shows only).
    var nextSeasonNumber: Int?

    /// Name of the next episode (TV shows only).
    var nextEpisodeName: String?

    /// Brief description of the media.
    var overview: String?

    /// Release date string (movies) or first air date (TV shows).
    var releaseDate: String?

    /// Average vote score (0-10).
    var voteAverage: Double?

    /// Number of votes.
    var voteCount: Int?

    /// Date when airing info was last refreshed.
    var lastRefreshed: Date?

    /// Raw watch state string for persistence.
    /// Nil means existing item (treated as .tracking for backwards compatibility).
    var watchStateRaw: String?

    /// Cached poster image data for widget display.
    @Attribute(.externalStorage) var posterData: Data?

    /// Whether the user has been notified that this movie is available to stream.
    /// Used to prevent duplicate "now streaming" notifications.
    var hasNotifiedAvailability: Bool

    /// Creates a new WatchlistItem.
    init(
        mediaId: Int,
        title: String,
        posterPath: String? = nil,
        backdropPath: String? = nil,
        overview: String? = nil,
        releaseDate: String? = nil,
        voteAverage: Double? = nil,
        voteCount: Int? = nil,
        dateAdded: Date = Date(),
        status: TVShowStatus = .unknown,
        mediaType: MediaType = .tv,
        nextEpisodeDate: Date? = nil,
        nextEpisodeNumber: Int? = nil,
        nextSeasonNumber: Int? = nil,
        nextEpisodeName: String? = nil,
        watchState: WatchState = .tracking,
        posterData: Data? = nil,
        hasNotifiedAvailability: Bool = false
    ) {
        self.mediaId = mediaId
        self.title = title
        self.posterPath = posterPath
        self.backdropPath = backdropPath
        self.overview = overview
        self.releaseDate = releaseDate
        self.voteAverage = voteAverage
        self.voteCount = voteCount
        self.dateAdded = dateAdded
        self.statusRaw = status.rawValue
        self.mediaTypeRaw = mediaType.rawValue
        self.nextEpisodeDate = nextEpisodeDate
        self.nextEpisodeNumber = nextEpisodeNumber
        self.nextSeasonNumber = nextSeasonNumber
        self.nextEpisodeName = nextEpisodeName
        self.lastRefreshed = Date()
        self.watchStateRaw = watchState.rawValue
        self.posterData = posterData
        self.hasNotifiedAvailability = hasNotifiedAvailability
    }

    /// The show's current status.
    var status: TVShowStatus {
        get { TVShowStatus(rawValue: statusRaw) ?? .unknown }
        set { statusRaw = newValue.rawValue }
    }

    /// The media type (tv or movie).
    /// Defaults to .tv for backwards compatibility with existing watchlist items.
    var mediaType: MediaType {
        get { MediaType(rawValue: mediaTypeRaw ?? "tv") ?? .tv }
        set { mediaTypeRaw = newValue.rawValue }
    }

    /// The watch state for this item.
    /// Defaults to .tracking for backwards compatibility with existing items.
    var watchState: WatchState {
        get { WatchState(rawValue: watchStateRaw ?? WatchState.tracking.rawValue) ?? .tracking }
        set { watchStateRaw = newValue.rawValue }
    }

    /// Whether this item is being actively tracked.
    var isTracking: Bool {
        watchState == .tracking
    }

    /// Whether this item has been watched.
    var isWatched: Bool {
        watchState == .watched
    }

    /// Whether this is a movie.
    var isMovie: Bool {
        mediaType == .movie
    }

    /// Whether this is a TV show.
    var isTVShow: Bool {
        mediaType == .tv
    }

    /// URL for the poster image.
    var posterURL: URL? {
        guard let path = posterPath else { return nil }
        return URL(string: "https://image.tmdb.org/t/p/w342\(path)")
    }

    /// URL for the backdrop image.
    var backdropURL: URL? {
        guard let path = backdropPath else { return nil }
        return URL(string: "https://image.tmdb.org/t/p/w780\(path)")
    }

    /// Updates the item with new airing info.
    /// If the item is watched and the incoming airing info has a future episode,
    /// auto-transition back to tracking so the user sees the returning show.
    func update(with airingInfo: TVShowAiringInfo) {
        if isWatched, let upcoming = airingInfo.nextEpisodeDate,
           upcoming >= Calendar.current.startOfDay(for: Date()) {
            watchState = .tracking
        }

        self.status = airingInfo.status
        self.nextEpisodeDate = airingInfo.nextEpisodeDate
        self.nextEpisodeNumber = airingInfo.nextEpisodeNumber
        self.nextSeasonNumber = airingInfo.nextSeasonNumber
        self.nextEpisodeName = airingInfo.nextEpisodeName

        if let newPoster = airingInfo.posterPath, newPoster != self.posterPath {
            self.posterPath = newPoster
            self.posterData = nil
        }
        if let newBackdrop = airingInfo.backdropPath, newBackdrop != self.backdropPath {
            self.backdropPath = newBackdrop
        }

        self.lastRefreshed = Date()
    }

    /// Converts this watchlist item to a Media object for use in detail views.
    func toMedia() -> Media {
        Media(
            id: mediaId,
            title: title,
            overview: overview ?? "",
            mediaType: mediaType,
            posterPath: posterPath,
            backdropPath: backdropPath,
            releaseDate: releaseDate,
            voteAverage: voteAverage ?? 0,
            voteCount: voteCount ?? 0
        )
    }

    /// Creates a WatchlistItem from a Media object and airing info.
    convenience init(from media: Media, airingInfo: TVShowAiringInfo? = nil, watchState: WatchState = .tracking, posterData: Data? = nil) {
        self.init(
            mediaId: media.id,
            title: media.title,
            posterPath: media.posterPath,
            backdropPath: media.backdropPath,
            overview: media.overview,
            releaseDate: media.releaseDate,
            voteAverage: media.voteAverage,
            voteCount: media.voteCount,
            status: airingInfo?.status ?? .unknown,
            mediaType: media.mediaType,
            nextEpisodeDate: airingInfo?.nextEpisodeDate,
            nextEpisodeNumber: airingInfo?.nextEpisodeNumber,
            nextSeasonNumber: airingInfo?.nextSeasonNumber,
            nextEpisodeName: airingInfo?.nextEpisodeName,
            watchState: watchState,
            posterData: posterData
        )
    }
}
