import Foundation

/// Metadata for a local notification, built from watchlist item data.
/// Pure value type with no UNUserNotificationCenter dependency (testable).
public struct NotificationContent: Sendable, Equatable {
    public let identifier: String
    public let title: String
    public let body: String
    public let categoryIdentifier: String
    public let threadIdentifier: String
    public let mediaId: Int
    public let mediaType: String
    public let triggerDate: Date?

    public init(
        identifier: String,
        title: String,
        body: String,
        categoryIdentifier: String,
        threadIdentifier: String,
        mediaId: Int,
        mediaType: String,
        triggerDate: Date? = nil
    ) {
        self.identifier = identifier
        self.title = title
        self.body = body
        self.categoryIdentifier = categoryIdentifier
        self.threadIdentifier = threadIdentifier
        self.mediaId = mediaId
        self.mediaType = mediaType
        self.triggerDate = triggerDate
    }
}

// MARK: - Notification Categories

public enum NotificationCategory: String, Sendable {
    case newEpisode
    case nowStreaming
}

// MARK: - Builder

public enum NotificationContentBuilder {

    /// Builds notification content for a new TV episode airing.
    /// Returns nil if the episode date is in the past or data is insufficient.
    /// - Parameters:
    ///   - mediaId: TMDB media ID.
    ///   - title: Show title.
    ///   - seasonNumber: Season number of the next episode.
    ///   - episodeNumber: Episode number of the next episode.
    ///   - episodeName: Name of the next episode, if available.
    ///   - airDate: The air date of the episode.
    ///   - currentDate: The current date for comparison (injectable for testing).
    public static func episodeNotification(
        mediaId: Int,
        title: String,
        seasonNumber: Int?,
        episodeNumber: Int?,
        episodeName: String?,
        airDate: Date,
        currentDate: Date = Date()
    ) -> NotificationContent? {
        // Don't schedule for past dates
        let calendar = Calendar.current
        guard calendar.startOfDay(for: airDate) >= calendar.startOfDay(for: currentDate) else {
            return nil
        }

        let body = episodeBody(seasonNumber: seasonNumber, episodeNumber: episodeNumber, episodeName: episodeName)

        // Trigger at 9 AM local time on the air date
        var components = calendar.dateComponents([.year, .month, .day], from: airDate)
        components.hour = 9
        components.minute = 0
        let triggerDate = calendar.date(from: components) ?? airDate

        return NotificationContent(
            identifier: "episode-\(mediaId)",
            title: title,
            body: body,
            categoryIdentifier: NotificationCategory.newEpisode.rawValue,
            threadIdentifier: "episode-\(mediaId)",
            mediaId: mediaId,
            mediaType: MediaType.tv.rawValue,
            triggerDate: triggerDate
        )
    }

    /// Builds notification content for a movie that is now streaming.
    /// - Parameters:
    ///   - mediaId: TMDB media ID.
    ///   - title: Movie title.
    ///   - serviceName: Name of the streaming service where it's available.
    public static func movieAvailableNotification(
        mediaId: Int,
        title: String,
        serviceName: String
    ) -> NotificationContent {
        NotificationContent(
            identifier: "streaming-\(mediaId)",
            title: title,
            body: "Now streaming on \(serviceName)",
            categoryIdentifier: NotificationCategory.nowStreaming.rawValue,
            threadIdentifier: "streaming-\(mediaId)",
            mediaId: mediaId,
            mediaType: MediaType.movie.rawValue,
            triggerDate: nil
        )
    }

    /// Checks which streaming providers match the user's selected service IDs.
    /// Returns the first matching provider name, or nil if no match.
    /// - Parameters:
    ///   - providers: Available streaming providers (flatrate).
    ///   - userServiceIDs: The user's selected service IDs.
    public static func matchingServiceName(
        providers: [WatchProvider],
        userServiceIDs: Set<Int>
    ) -> String? {
        guard !userServiceIDs.isEmpty else { return nil }
        return providers.first { userServiceIDs.contains($0.id) }?.name
    }

    /// Returns the number of episode air dates that fall after `lastOpenedDate`.
    /// Used to calculate the app badge count independently of Notification Center state.
    /// - Parameters:
    ///   - episodeDates: Air dates for upcoming episodes (9 AM trigger times,
    ///     as produced by ``episodeNotification(mediaId:title:seasonNumber:episodeNumber:episodeName:airDate:currentDate:)``).
    ///   - lastOpenedDate: The last time the user foregrounded the app.
    /// - Returns: Count of episodes the user has not yet seen (aired after last open).
    public static func badgeCount(
        episodeDates: [Date],
        lastOpenedDate: Date
    ) -> Int {
        episodeDates.filter { $0 > lastOpenedDate }.count
    }

    // MARK: - Private

    private static func episodeBody(seasonNumber: Int?, episodeNumber: Int?, episodeName: String?) -> String {
        let name = episodeName?.trimmingCharacters(in: .whitespacesAndNewlines)
        let hasName = name != nil && !name!.isEmpty

        if let season = seasonNumber, let episode = episodeNumber {
            let tag = "S\(season) E\(episode)"
            return hasName ? "\(name!) (\(tag)) airs today" : "\(tag) airs today"
        } else if let season = seasonNumber {
            return hasName ? "\(name!) (Season \(season)) airs today" : "Season \(season) airs today"
        } else {
            return hasName ? "\(name!) airs today" : "New episode airs today"
        }
    }
}
