import Foundation

/// Information about a TV show's airing status and upcoming episodes.
public struct TVShowAiringInfo: Sendable {
    /// The show's current status.
    public let status: TVShowStatus

    /// Air date of the next episode, if known.
    public let nextEpisodeDate: Date?

    /// Episode number of the next episode.
    public let nextEpisodeNumber: Int?

    /// Season number of the next episode.
    public let nextSeasonNumber: Int?

    /// Name of the next episode, if available.
    public let nextEpisodeName: String?

    /// Current poster path from TMDB.
    public let posterPath: String?

    /// Current backdrop path from TMDB.
    public let backdropPath: String?

    /// Creates a new TVShowAiringInfo instance.
    public init(
        status: TVShowStatus,
        nextEpisodeDate: Date? = nil,
        nextEpisodeNumber: Int? = nil,
        nextSeasonNumber: Int? = nil,
        nextEpisodeName: String? = nil,
        posterPath: String? = nil,
        backdropPath: String? = nil
    ) {
        self.status = status
        self.nextEpisodeDate = nextEpisodeDate
        self.nextEpisodeNumber = nextEpisodeNumber
        self.nextSeasonNumber = nextSeasonNumber
        self.nextEpisodeName = nextEpisodeName
        self.posterPath = posterPath
        self.backdropPath = backdropPath
    }

    /// Whether the show has an upcoming episode (today or in the future).
    public var hasUpcomingEpisode: Bool {
        guard let days = daysUntilNextEpisode else { return false }
        return days >= 0
    }

    /// Number of days until the next episode airs.
    /// Returns nil if no next episode date is available.
    public var daysUntilNextEpisode: Int? {
        guard let nextDate = nextEpisodeDate else { return nil }
        let calendar = Calendar.current
        let now = calendar.startOfDay(for: Date())
        let next = calendar.startOfDay(for: nextDate)
        let components = calendar.dateComponents([.day], from: now, to: next)
        return components.day
    }

    /// Formatted countdown string for display.
    /// Returns nil if no next episode date is available.
    public var countdownText: String? {
        guard let days = daysUntilNextEpisode else { return nil }

        switch days {
        case ..<0:
            return nil // Episode already aired
        case 0:
            return "Today"
        case 1:
            return "Tomorrow"
        case 2...7:
            return "\(days)d"
        default:
            let weeks = days / 7
            return weeks == 1 ? "1 week" : "\(weeks) weeks"
        }
    }
}
