import Foundation

/// Policy for determining when to refresh watchlist airing information.
public struct WatchlistRefreshPolicy: Sendable {
    /// Minimum hours between automatic refreshes.
    public let refreshIntervalHours: Int

    /// Creates a refresh policy with the given interval.
    /// - Parameter refreshIntervalHours: Hours between refreshes. Defaults to 24.
    public init(refreshIntervalHours: Int = 24) {
        self.refreshIntervalHours = refreshIntervalHours
    }

    /// Determines if a refresh is needed based on the last refresh date.
    /// - Parameters:
    ///   - lastRefreshDate: The date of the last refresh, or nil if never refreshed.
    ///   - currentDate: The current date to compare against.
    /// - Returns: True if refresh is needed (more than refreshIntervalHours since last refresh).
    public func needsRefresh(lastRefreshDate: Date?, currentDate: Date = Date()) -> Bool {
        guard let lastRefresh = lastRefreshDate else {
            return true
        }

        let hoursSinceRefresh = Calendar.current.dateComponents(
            [.hour],
            from: lastRefresh,
            to: currentDate
        ).hour ?? refreshIntervalHours

        return hoursSinceRefresh >= refreshIntervalHours
    }

    /// Calculates hours until next refresh is allowed.
    /// - Parameters:
    ///   - lastRefreshDate: The date of the last refresh.
    ///   - currentDate: The current date.
    /// - Returns: Hours until refresh, or 0 if refresh is due.
    public func hoursUntilRefresh(lastRefreshDate: Date?, currentDate: Date = Date()) -> Int {
        guard let lastRefresh = lastRefreshDate else {
            return 0
        }

        let hoursSinceRefresh = Calendar.current.dateComponents(
            [.hour],
            from: lastRefresh,
            to: currentDate
        ).hour ?? 0

        let hoursRemaining = refreshIntervalHours - hoursSinceRefresh
        return max(0, hoursRemaining)
    }
}
