import Foundation
import BackgroundTasks
import SwiftData
import WCIWKit

/// Manages Background App Refresh tasks for checking movie availability.
@MainActor
final class BackgroundTaskManager {
    static let shared = BackgroundTaskManager()

    /// Task identifier for movie availability checks.
    static let availabilityCheckIdentifier = "com.tommcfarlin.watchit.availability-check"

    private init() {}

    // MARK: - Registration

    /// Registers the background task with the system.
    /// Must be called before the end of `application(_:didFinishLaunchingWithOptions:)`.
    func registerTasks() {
        BGTaskScheduler.shared.register(
            forTaskWithIdentifier: Self.availabilityCheckIdentifier,
            using: nil
        ) { task in
            guard let refreshTask = task as? BGAppRefreshTask else { return }
            Task { @MainActor in
                await self.handleAvailabilityCheck(task: refreshTask)
            }
        }
    }

    /// Schedules the next background refresh.
    func scheduleAvailabilityCheck() {
        let request = BGAppRefreshTaskRequest(identifier: Self.availabilityCheckIdentifier)
        // Request no earlier than 2 hours from now
        request.earliestBeginDate = Date(timeIntervalSinceNow: 2 * 60 * 60)

        do {
            try BGTaskScheduler.shared.submit(request)
        } catch {
            // Non-fatal — iOS may reject scheduling
        }
    }

    // MARK: - Task Handling

    /// Handles the background availability check task.
    private func handleAvailabilityCheck(task: BGAppRefreshTask) async {
        // Schedule the next check before starting work
        scheduleAvailabilityCheck()

        // Only check if premium and notifications enabled
        guard NotificationManager.shared.shouldScheduleNotifications() else {
            task.setTaskCompleted(success: true)
            return
        }

        guard let tmdbService = try? TMDBService() else {
            task.setTaskCompleted(success: false)
            return
        }

        let userServiceIDs = UserServicesManager.shared.selectedServiceIDs
        guard !userServiceIDs.isEmpty else {
            task.setTaskCompleted(success: true)
            return
        }

        // Set up expiration handler
        task.expirationHandler = {
            // Task ran out of time — will try again next cycle
        }

        do {
            // Create a model container to access watchlist data
            let schema = Schema([WatchlistItem.self])
            let config = ModelConfiguration(schema: schema, isStoredInMemoryOnly: false, cloudKitDatabase: .none)
            let container = try ModelContainer(for: schema, configurations: [config])
            let context = ModelContext(container)

            // Fetch movies that haven't been notified yet
            let descriptor = FetchDescriptor<WatchlistItem>(
                predicate: #Predicate<WatchlistItem> {
                    $0.hasNotifiedAvailability == false
                }
            )
            let items = (try? context.fetch(descriptor)) ?? []
            let movies = items.filter { $0.isMovie }

            // Check each movie's availability
            for movie in movies {
                let media = movie.toMedia()

                do {
                    let availability = try await tmdbService.getWatchProviders(for: media)
                    let streamingProviders = availability.flatrate

                    if let serviceName = NotificationContentBuilder.matchingServiceName(
                        providers: streamingProviders,
                        userServiceIDs: userServiceIDs
                    ) {
                        // Match found — notify and mark
                        await NotificationManager.shared.notifyMovieAvailable(
                            item: movie,
                            serviceName: serviceName
                        )
                        movie.hasNotifiedAvailability = true
                    }
                } catch {
                    // Skip this movie, try next
                    continue
                }
            }

            // Also reschedule episode notifications
            let allItems = (try? context.fetch(FetchDescriptor<WatchlistItem>())) ?? []
            await NotificationManager.shared.rescheduleEpisodeNotifications(items: allItems)

            try? context.save()
            task.setTaskCompleted(success: true)
        } catch {
            task.setTaskCompleted(success: false)
        }
    }
}
```

---

## Key Implementation Details

**Notification Rescheduling Flow:**

1. **Entry Points:** `rescheduleEpisodeNotifications` is called from:
   - `WatchlistManager.refreshAllAiringInfo()` after fetching updated airing data
   - `BackgroundTaskManager.handleAvailabilityCheck()` during background refresh

2. **Algorithm:**
   - Removes all existing episode notifications (filtering by "episode-" prefix)
   - Iterates through TV show watchlist items with valid `nextEpisodeDate`
   - Uses `NotificationContentBuilder.episodeNotification()` to build notification metadata
   - Validates air dates are today or in the future
   - Sorts notifications chronologically by air date
   - Assigns badge numbers sequentially (1, 2, 3...) only to episodes airing after `lastOpenedDate`
   - Episodes before `lastOpenedDate` are scheduled without badge modification

3. **Badge Management:**
   - Badge values are calculated independently of Notification Center state
   - Prevents badge inflation by using `lastOpenedDate` as the baseline
   - `clearBadge()` is called when the app enters foreground, updating `lastOpenedDate`

4. **Episode Tracking:**
   - `WatchedEpisode` model uses `mediaId` to link to watchlist items (no SwiftData relationship)
   - Cascade deletion removes all watched episodes when a show is removed
   - Watch state management supports `.tracking` and `.watched` states

